-- Catálogo oficial RCD: centros de secundaria de la provincia de Toledo.
-- Fuente: https://www.educacion.gob.es/centros/

values ('45200', 'Illescas', 'Toledo', 'Castilla-La Mancha')
on conflict (postal_code, municipality) do update set
  province = excluded.province,
  autonomous_region = excluded.autonomous_region;

on conflict (official_code) do update set
  name = excluded.name,
  generic_name = excluded.generic_name,
  municipality = excluded.municipality,
  province = excluded.province,
  autonomous_region = excluded.autonomous_region,
  ownership = excluded.ownership,
  source_url = excluded.source_url,
  is_active = excluded.is_active;
